node -e "
const AdmZip = require('adm-zip');
const PDFDocument = require('pdfkit');
const fs = require('fs');

// Extract text from docx
const zip = new AdmZip('/workspace/testbed/docs/customer_report.docx');
const xml = zip.readAsText('word/document.xml');

// Parse paragraphs with style info
const paragraphs = [];
const pSections = xml.split(/<\/w:p>/);
for (const p of pSections) {
  const texts = [];
  const re = /<w:t[^>]*>([^<]*)<\/w:t>/g;
  let m;
  while ((m = re.exec(p)) !== null) {
    texts.push(m[1]);
  }
  const line = texts.join('');
  // Detect heading style
  const styleMatch = p.match(/<w:pStyle w:val=\"([^\"]*)\"/);
  const style = styleMatch ? styleMatch[1] : '';
  const isBold = p.includes('<w:b/>') || p.includes('<w:b ');
  paragraphs.push({ text: line, style, isBold });
}

// Build PDF
const doc = new PDFDocument({ margin: 50, size: 'A4' });
const out = fs.createWriteStream('/workspace/testbed/docs/customer_report.pdf');
doc.pipe(out);

for (const para of paragraphs) {
  const text = para.text;
  if (!text && !para.style) {
    doc.moveDown(0.3);
    continue;
  }

  if (para.style === 'Title' || (paragraphs.indexOf(para) === 0 && text)) {
    doc.fontSize(20).font('Helvetica-Bold').text(text);
    doc.moveDown(0.5);
  } else if (para.style.startsWith('Heading') || (para.isBold && !text.startsWith(' '))) {
    doc.fontSize(13).font('Helvetica-Bold').text(text);
    doc.moveDown(0.2);
  } else if (text.startsWith('  ')) {
    doc.fontSize(10).font('Helvetica').text(text);
    doc.moveDown(0.1);
  } else if (text) {
    doc.fontSize(10).font('Helvetica').text(text);
    doc.moveDown(0.1);
  }
}

doc.end();
out.on('finish', () => {
  console.log('PDF created: /workspace/testbed/docs/customer_report.pdf');
  const stats = fs.statSync('/workspace/testbed/docs/customer_report.pdf');
  console.log('Size:', (stats.size / 1024).toFixed(1), 'KB');
});
"

